using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Godot;
using RingworldTechDemo.Voxel.Core;
using RingworldTechDemo.Voxel.Phase2;
using RingworldTechDemo.Voxel.Phase3;
using RingworldTechDemo.Voxel.LOD;

namespace RingworldTechDemo.Terrain.Editable;

public partial class SmoothConstructionOverlaySmoke : Node
{
 public override async void _Ready(){if(!Array.Exists(OS.GetCmdlineUserArgs(),a=>a=="--smooth-construction-overlay-smoke")){GetTree().Quit();return;}try{
  const long length=128;var g=new RingLodGeometrySnapshot(Transform3D.Identity,Vector3.Zero,Vector3.Zero,1000,0,0,length,-10,10,null);var test=new Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial>{{new(0,0,0),SmoothConstructionMaterial.Concrete}};var a=SmoothConstructionMesher.Build(new(0,0,0),test,length,g,Transform3D.Identity);var b=SmoothConstructionMesher.Build(new(0,0,0),test,length,g,Transform3D.Identity);if(a.Hash!=b.Hash||a.Indices.Length!=36)throw new Exception("deterministic one-block mesh");for(int q=0;q<a.Indices.Length;q+=3){Vector3 face=(a.Vertices[a.Indices[q+1]]-a.Vertices[a.Indices[q]]).Cross(a.Vertices[a.Indices[q+2]]-a.Vertices[a.Indices[q]]);if(face.Dot(a.Normals[a.Indices[q]]+a.Normals[a.Indices[q+1]]+a.Normals[a.Indices[q+2]])>=0)throw new Exception("construction face winding is not Godot-clockwise");}test[new(1,0,0)]=SmoothConstructionMaterial.Glass;if(SmoothConstructionMesher.Build(new(0,0,0),test,length,g,Transform3D.Identity).Indices.Length!=60)throw new Exception("shared face");var edge=new Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial>{{new(31,0,0),SmoothConstructionMaterial.Concrete},{new(32,0,0),SmoothConstructionMaterial.Glass}};if(SmoothConstructionMesher.Build(new(0,0,0),edge,length,g,Transform3D.Identity).Indices.Length/6+SmoothConstructionMesher.Build(new(1,0,0),edge,length,g,Transform3D.Identity).Indices.Length/6!=10)throw new Exception("cross-chunk exterior count");
  var source=new VoxelChunkGridManager{BuildOnReady=false,EnableChunkStreaming=false,AroundRingChunkLength=4,RingAcrossWidthMeters=128,UseRingCurvedPlacement=true,EnableCanonicalFloatingOriginAnchor=true};source.Name="Source";AddChild(source);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  var overlay=new SmoothConstructionOverlay{SourceGridPath=new NodePath("../Source"),MaxWorkers=1,MaxInstallsPerFrame=8};AddChild(overlay);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  ulong id=1;void Apply(bool place,long x,int y,int z,SmoothConstructionMaterial m)=>overlay.Apply(new SmoothConstructionCommand(1,id,id++,place,new SmoothConstructionBlock(x,y,z),m));
  Apply(true,0,8,0,SmoothConstructionMaterial.Concrete);await Wait(overlay);var s=overlay.CaptureDebugState();if(s.Count!=1||!s[new(0,0,0)].Opaque||!s[new(0,0,0)].Collision||overlay.EstimatedBytes<=0)throw new Exception("real one-block resources");var grassConcrete=overlay.CaptureGrassExclusionSnapshot();if(!ReferenceEquals(grassConcrete,overlay.CaptureGrassExclusionSnapshot())||grassConcrete.Boxes.Count!=1||!grassConcrete.IsExcluded(.5,8.1,.5,.2f))throw new Exception("grass exclusion cache/concrete");int created=overlay.CreatedPresenterCount;
  Apply(true,1,8,0,SmoothConstructionMaterial.Glass);await Wait(overlay);s=overlay.CaptureDebugState();if(s.Count!=1||!s[new(0,0,0)].Glass||!s[new(0,0,0)].Opaque)throw new Exception("real glass/concrete");var grassMixed=overlay.CaptureGrassExclusionSnapshot();if(ReferenceEquals(grassConcrete,grassMixed)||grassMixed.Boxes.Count!=2||!grassMixed.IsExcluded(1.5,8.1,.5,.2f)||!grassConcrete.IsExcluded(.5,8.1,.5,.2f))throw new Exception("grass exclusion immutable glass/concrete");
  Apply(true,31,8,0,SmoothConstructionMaterial.Concrete);Apply(true,32,8,0,SmoothConstructionMaterial.Glass);await Wait(overlay);s=overlay.CaptureDebugState();if(!s.ContainsKey(new(0,0,0))||!s.ContainsKey(new(1,0,0)))throw new Exception("cross chunk resident");
  Apply(true,127,8,0,SmoothConstructionMaterial.Concrete);await Wait(overlay);s=overlay.CaptureDebugState();if(!s.ContainsKey(new(3,0,0)))throw new Exception("seam resident");var before=s[new(0,0,0)];
  overlay.SuspendInstallsForTests=true;if(!overlay.RebuildForTests(new(0,0,0)))throw new Exception("stale hook");for(int q=0;q<120&&overlay.ReadyResultCount==0;q++)await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);Apply(true,2,8,0,SmoothConstructionMaterial.Concrete);overlay.SuspendInstallsForTests=false;await Wait(overlay);if(overlay.StaleResults<1||overlay.MaxActiveWorkers>1)throw new Exception("stale/worker cap");
  var positions=overlay.CapturePresenterPositionsForTests();ulong hashBeforeAnchor=overlay.CaptureDebugState()[new(0,0,0)].Hash;source.SetFloatingOriginCanonicalAnchor(new RingCanonicalPosition(16,8,0));await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);var moved=overlay.CapturePresenterPositionsForTests();if(positions[new(0,0,0)].IsEqualApprox(moved[new(0,0,0)]))throw new Exception("reanchor position");if(hashBeforeAnchor!=overlay.CaptureDebugState()[new(0,0,0)].Hash)throw new Exception("reanchor hash");
  var journal=overlay.CaptureCommands();string journalPath=ProjectSettings.GlobalizePath("user://smooth_construction_runtime_smoke.json");System.IO.File.WriteAllText(journalPath,System.Text.Json.JsonSerializer.Serialize(journal));var loaded=System.Text.Json.JsonSerializer.Deserialize<SmoothConstructionCommand[]>(System.IO.File.ReadAllText(journalPath));System.IO.File.Delete(journalPath);if(loaded==null||!overlay.ReplaceCommands(loaded))throw new Exception("file replace replay");await Wait(overlay);var grassReplayed=overlay.CaptureGrassExclusionSnapshot();if(overlay.BlockCount!=6||grassReplayed.Boxes.Count!=6||!grassReplayed.IsExcluded(1.5,8.1,.5,.2f))throw new Exception("replay grass exclusion bridge");
  foreach(var c in overlay.CaptureCommands())if(c.Place)Apply(false,c.Block.Around,c.Block.Vertical,c.Block.Across,c.Material);await Wait(overlay);var grassEmpty=overlay.CaptureGrassExclusionSnapshot();if(ReferenceEquals(grassEmpty,grassMixed)||grassEmpty.Boxes.Count!=0||!grassMixed.IsExcluded(1.5,8.1,.5,.2f))throw new Exception("grass exclusion remove cache");if(overlay.PresenterCount!=0||overlay.PoolCount<1||overlay.CreatedPresenterCount!=created&&overlay.ReusedPresenterCount==0)throw new Exception("empty unload/pool");
  Task shutdown=overlay.AwaitShutdownForTestsAsync();overlay.QueueFree();for(int q=0;q<240&&!shutdown.IsCompleted;q++)await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await shutdown;if(overlay.TaskCount!=0||overlay.ActiveWorkers!=0||overlay.ReadyResultCount!=0||overlay.PresenterCount!=0||overlay.EstimatedBytes!=0)throw new Exception("shutdown");GD.Print("SMOOTH_CONSTRUCTION_OVERLAY_SMOKE_TEST_PASS");GetTree().Quit();
 }catch(Exception e){GD.PushError(e.ToString());GD.Print("SMOOTH_CONSTRUCTION_OVERLAY_SMOKE_TEST_FAIL");GetTree().Quit(1);}}
 private async Task Wait(SmoothConstructionOverlay o){for(int i=0;i<360&&!o.IsQuiescent;i++)await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);if(!o.IsQuiescent)throw new Exception("overlay quiescence");}
}
